    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'fGykTWeoGzfq-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'fGykTWeoGzfq-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "סכם", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-18T14:09:05.815567'::timestamptz - interval '1 second'),
