    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'vo60NBnbleh3-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'vo60NBnbleh3-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "בשמחה! הנה מתכון קלאסי לחמין:\n\nמרכיבים:\n- 1 ק\"ג בשר צלי (נתח שלם)\n- 5 תפוחי אדמה גדולים, קלופים וחתוכים לרבעים\n- 3 בצלים גדולים, חתוכים לרבעים\n- 1 כוס גרגרי חומוס\n- 1 כוס שעועית לבנה\n- 4 ביצים שלמות\n- 1/2 כוס שמן זית\n- 4 כפות רסק עגבניות\n- 1 כפית כמון\n- 1 כפית פפריקה מתוקה\n- מלח ופלפל שחור לפי הטעם\n- 3-4 כוסות מים\n\nאופן ההכנה:\n1. שרו את החומוס והשעועית במים למשך לילה כדי לרכך אותם.\n2. בסיר גדול, חממו את שמן הזית וטגנו את הבצלים עד שהם מתרככים ומזהיבים.\n3. הוסיפו את הבשר וטגנו מכל הצדדים עד שהוא משחים.\n4. הוסיפו את רסק העגבניות, הכמון, הפפריקה, המלח והפלפל. טעמו והתאימו תיבול לפי הטעם.\n5. הוסיפו את החומוס והשעועית המשוריים, תפוחי האדמה, הביצים והמים. הביאו לרתיחה.\n6. כסו את הסיר במכסה והורידו את הלהבה לנמוכה. תנו לחמין לבשל בהבעבוע עדין למשך לפחות 12 שעות. בדקו מדי פעם שיש מספיק נוזלים והוסיפו מים אם צריך.\n7. לפני ההגשה, טעמו שוב ותקנו תיבול אם צריך.\n\nתהנו מארוחת שבת חמה וטעימה!", "type": "text"}]}'::jsonb, 25068, '2025-05-18T08:08:30.242463'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'zQRhpX7LNdUl-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'zQRhpX7LNdUl-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "היי מה קורה?", "type": "text"}]}'::jsonb, NULL::integer, '2025-09-03T08:24:19.429214'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'zQRhpX7LNdUl-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'zQRhpX7LNdUl-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "היי! הכל בסדר, תודה ששאלת. איך אני יכול לעזור לך היום?", "type": "text"}]}'::jsonb, 0, '2025-09-03T08:24:19.429214'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'daWr1AQPxtCl-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'daWr1AQPxtCl-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "מי זאת חברת JEEN?", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-15T12:18:33.241149'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'daWr1AQPxtCl-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'daWr1AQPxtCl-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "חברת Jeen.ai היא חברה ישראלית המתמחה בפיתוח והטמעה של יישומי בינה מלאכותית יוצרת (GenAI) בארגונים גדולים. החברה הוקמה ביולי 2024 כספין-אוף של פעילות ה-GenAI מקבוצת וואן טכנולוגיות, אשר מחזיקה ב-25% ממנה[$url: https://www.ittime.co.il/exposed-jeen-ai$, content: Jeen.ai החלה את דרכה כספין-אוף של פעילות ה-GenAI בוואן טכנולוגיות, אשר מחזיקה ב-25% ממנה, ויצאה לדרך עצמאית ביולי 2024 עם כ-25 עובדים, במטרה להעמיק את פעילותה בשוק הגלובלי ולצאת לאפשרויות גיוס בשוק ..$]. החברה מציעה פלטפורמה מאובטחת להטמעה מהירה של יישומי GenAI, המיועדת לארגונים גדולים, ומספקת כלים מותאמים אישית, שירותים ותמיכה[$url: https://jeen.ai/about/$, content: Jeen is the driving force that brings enterprises to the forefront of technology — providing custom-built tools, services, and support. We’re here to walk alongside every organization into a future sh…$]. \n\nלאחרונה, החברה השלימה מיזוג עם חברת מיקרונט ונכנסה למסחר בבורסה בתל-אביב[$url: https://www.israelhayom.co.il/business/article/17946005$, content: למעשה חברת Jeen.ai השלימה את המיזוג עם מיקרונט והקצאת המניות לאחר השלמת כלל התנאים המתלים של העסקה. לאחר הקצאת המניות וכן הסכמי השקעה שנחתמו כחלק מהמיזוג - משקף מחיר המניה הנוכחי (3.08 שקל) שווי של כ-…$].", "type": "text"}]}'::jsonb, 4993, '2025-05-15T12:18:33.241149'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'DqC556SI16LL-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'DqC556SI16LL-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "שבוע שעבר", "type": "text"}]}'::jsonb, NULL::integer, '2025-11-05T09:13:15.711647'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'DqC556SI16LL-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'DqC556SI16LL-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "להלן כלל הפגישות שהוקלטו ותומללו באפליקציית Teams בטווח התאריכים (2025-10-27 → 2025-11-02):\n- 1. סטטוס פרויקטים | 2025-11-02\n2. Market Research- Summary | 2025-10-30\n3. מענה בצירוף אקסל | 2025-10-28\n\nאנא ציינו מספר פגישה להצגת הסיכום.", "type": "text"}]}'::jsonb, 6826, '2025-11-05T09:13:15.711647'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'GtwMHb2frvu0-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'GtwMHb2frvu0-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "אתה מומחה בהסברה. כתוב לי שלב שלב איך להתחבר למערכת שלהם", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-20T09:10:13.109290'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'GtwMHb2frvu0-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'GtwMHb2frvu0-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "כמובן, הנה מדריך שלב-אחר-שלב להתחברות למערכת Okta Verify של Ormat Systems:\n\n### חלק 1 – יצירת חשבון עם מחשב אישי\n\n1. **התחברות לאתר Okta:**\n   - התחבר למחשב האישי שלך או למכשיר טלפון שני וגש לאתר Okta בכתובת: [https://ormat.okta.com](https://ormat.okta.com).\n\n2. **התחברות לחשבון:**\n   - השתמש בשם המשתמש והסיסמה שלך כדי להתחבר לחשבון שלך.\n\n3. **גישה להגדרות:**\n   - בפינה הימנית העליונה של החלון, לחץ על החץ הנפתח ליד שמך ובחר ב-\"Settings\" (הגדרות).\n\n4. **הגדרת אימות נוסף:**\n   - גלול למטה עד שתראה את הסעיף \"Extra Verification\" בצד ימין ולחץ על \"Set up\" (הגדר).\n\n5. **הגדרת גורם אימות:**\n   - לחץ על \"Configure factor\" (הגדר גורם).\n\n6. **רישום משתמש חדש (אם אתה משתמש חדש):**\n   - דלג על שלב זה אם אתה משתמש קיים.\n   - אם אתה משתמש חדש, דף הרישום ייפתח. מלא את הפרטים הבאים:\n     - דוא\"ל משני (הכנס את חשבון ה-Gmail האישי שלך).\n     - שאלה אבטחה (בחר שאלה ושמור את התשובה, IT לא יוכל לשחזר או לשנות אותה).\n     - אימות SMS (בחר את המדינה שלך \"IL +972\" והוסף את מספר הטלפון שלך והקוד).\n   - בתחתית הדף, בחר \"Create my Account\" (צור את החשבון שלי).\n\n7. **בחירת סוג טלפון:**\n   - בחר \"Android\" או \"iPhone\" בהתאם לסוג הטלפון שלך ולחץ על \"Next\" (הבא).\n\n8. **קבלת קוד QR:**\n   - כעת יופיע קוד QR לסריקה בשלב הבא.\n\n### חלק 2 – סריקת קוד QR עם סמארטפון\n\n9. **התקנת אפליקציית Okta Verify:**\n   - פתח את הסמארטפון האישי שלך והתקן את אפליקציית \"Okta Verify\" מחנות Google Play או Apple App Store.\n\n10. **הוספת חשבון:**\n    - פתח את האפליקציה ולחץ על \"Add Account\" (הוסף חשבון).\n\n11. **בחירת סוג חשבון:**\n    - בחר \"Organization\" (ארגון).\n\n12. **אישור סריקה:**\n    - בחר \"Yes\" (כן) כדי לאשר את הסריקה.\n\n13. **סריקת קוד QR:**\n    - הסכם לסרוק את הברקוד וסרוק את קוד ה-QR מהמחשב מהשלב הקודם.\n\n14. **אימות וסיום:**\n    - לאחר סריקת הקוד, תופיע הודעה \"Account Added\" (חשבון נוסף). כעת, הכנס את הקוד במחשב ולחץ על \"Verify\" (אמת).\n\nוזהו! סיימת את תהליך ההתחברות למערכת Okta Verify.", "type": "text"}]}'::jsonb, 9133, '2025-05-20T09:10:13.109290'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'FCFze0uPNMf2-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'FCFze0uPNMf2-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "אתה מומחה הדרכה בניית סוכנים בפלטפורה של Jeen.ai.\nכתוב בשלבים מה נדרש למלא בכל שלב בבניית סוכן וההשפעות של זה. תהיה ממוקד תכתוב שלבי עבודה עם נקודות", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-20T14:13:19.399901'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'FCFze0uPNMf2-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'FCFze0uPNMf2-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "כמובן, הנה מדריך שלב-אחר-שלב לבניית סוכן בפלטפורמת Jeen.ai:\n\n### שלב 1: התחברות לפלטפורמה\n1. **התחבר לחשבון שלך ב-Jeen.ai:**\n   - גש לאתר Jeen.ai והתחבר באמצעות שם המשתמש והסיסמה שלך.\n\n### שלב 2: יצירת סוכן חדש\n2. **לחיצה על כפתור \"New Agent\":**\n   - לאחר ההתחברות, לחץ על כפתור \"New Agent\" כדי להתחיל בתהליך יצירת הסוכן.\n\n### שלב 3: מילוי פרטי הסוכן\n3. **מילוי השדות הבאים:**\n   - **Agent Name (שם הסוכן):**\n     - הזן שם ייחודי לסוכן שלך. שם זה יופיע ברשימת הסוכנים.\n   - **Description (תיאור):**\n     - ספק תיאור קצר של הסוכן, כולל מטרתו וקהל היעד שלו.\n   - **Language (שפה):**\n     - בחר את השפה בה הסוכן יתקשר עם המשתמשים.\n\n### שלב 4: הגדרת פרומפט אופי (Character Prompt)\n4. **הגדרת פרומפט אופי:**\n   - **מטרת הפרומפט:**\n     - קביעת סגנון הדיבור, עולם התוכן ומטרת השירות שהסוכן נותן.\n   - **דוגמה:**\n     - \"הסוכן הוא נציג מכירות צעיר שמטרתו למכור ציוד אלקטרוני.\"\n   - **השפעה:**\n     - פרומפט זה יקבע את האופי והטון של התשובות שהסוכן יספק.\n\n### שלב 5: הוספת מסמכים (Documents)\n5. **הוספת מסמכים לסוכן:**\n   - **לחיצה על כפתור \"Documents\":**\n     - הוסף מסמכים רלוונטיים עליהם יתבסס הסוכן במתן תשובות.\n   - **בחירת מסמכים:**\n     - בחר את המסמכים הרלוונטיים ולחץ על \"Save to Bot\".\n   - **השפעה:**\n     - המסמכים ישמשו כמקור מידע לתשובות שהסוכן יספק.\n\n### שלב 6: הגדרת פרומפט ניתוח (Analysis Prompt)\n6. **הגדרת פרומפט ניתוח:**\n   - **מטרת הפרומפט:**\n     - לנסח מחדש את שאלת המשתמש ולזקק אותה לטובת חיפוש התשובה המתאימה ביותר מהמסמכים.\n   - **דוגמה:**\n     - \"User Wants: [one sentence in English]\"\n   - **השפעה:**\n     - פרומפט זה יסייע לסוכן להבין את כוונת המשתמש בצורה מדויקת יותר.\n\n### שלב 7: הגדרת פרומפט ציון (Grade Prompt)\n7. **הגדרת פרומפט ציון:**\n   - **מטרת הפרומפט:**\n     - קבלת מספר תשובות אפשריות ומתן ציון לכל תשובה.\n   - **דוגמה:**\n     - \"source1: [relevance score from 0 to 100]\"\n   - **השפעה:**\n     - פרומפט זה יסייע לסנן תשובות לא רלוונטיות ולבחור את התשובה המתאימה ביותר.\n\n### שלב 8: הגדרת פרומפט ניסוח (Relevant Answer Prompt)\n8. **הגדרת פרומפט ניסוח:**\n   - **מטרת הפרומפט:**\n     - ניסוח התשובה הסופית למשתמש.\n   - **דוגמה:**\n     - \"Lets think step by step. Whats the best answer to the users question based on the provided list of sources?\"\n   - **השפעה:**\n     - פרומפט זה יבטיח שהתשובה תהיה מדויקת ומבוססת על המידע שסופק.\n\n### שלב 9: הגדרת הודעות נוספות (Optional)\n9. **הגדרת הודעות נוספות:**\n   - **No Relevant Message:**\n     - הודעה שתישלח למשתמש כשלא נמצא מידע רלוונטי.\n   - **Hack Prompt:**\n     - פרומפט לסינון שאלות לא רלוונטיות או פניות לא ראויות.\n   - **Hack Message:**\n     - הודעה שתישלח במקרים בהם השאלה שהלקוח שאל מקבלת False מהפרומפט פריצה.\n\n### שלב 10: שמירת הסוכן\n10. **שמירת הסוכן:**\n    - לאחר מילוי כל השדות והגדרות הפרומפטים, לחץ על כפתור \"Save\" כדי לשמור את הסוכן החדש.\n\n### שלב 11: בדיקה והתאמה\n11. **בדיקת הסוכן:**\n    - בדוק את הסוכן על ידי שליחת שאלות ובחינת התשובות שהוא מספק.\n    - בצע התאמות ושיפורים לפי הצורך.\n\nוזהו! סיימת את תהליך בניית הסוכן בפלטפורמת Jeen.ai.", "type": "text"}]}'::jsonb, 13722, '2025-05-20T14:13:19.399901'::timestamptz),
