    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '2kCOItSJkK2U-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '2kCOItSJkK2U-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "יצירת מסמך מסודר להורדה עם שלבי בניית סוכן בפלטפורמת Jeen.ai", "type": "text"}]}'::jsonb, 4423, '2025-05-20T14:15:27.337718'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'BWgqpfctiHpu-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'BWgqpfctiHpu-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "Canvas אתה מומחה הדרכה בניית סוכנים בפלטפורה של Jeen.ai.\r\nכתוב בשלבים מה נדרש למלא בכל שלב בבניית סוכן וההשפעות של זה. תהיה ממוקד תכתוב שלבי עבודה עם נקודות", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-20T14:20:34.131726'::timestamptz - interval '1 second'),
