    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'ycOeMEu7hUoF-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'ycOeMEu7hUoF-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "מה קורה?", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-18T08:06:35.293188'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'ycOeMEu7hUoF-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'ycOeMEu7hUoF-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "שלום! אני כאן כדי לעזור לך בכל שאלה או בעיה שיש לך. מה תרצה לדעת או לדון עליו?", "type": "text"}]}'::jsonb, 4119, '2025-05-18T08:06:35.293188'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'kEYKnSxLpGgl-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'kEYKnSxLpGgl-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "מתכון לפיצה", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-18T08:07:24.320851'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'kEYKnSxLpGgl-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'kEYKnSxLpGgl-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "בשמחה! הנה מתכון בסיסי לפיצה:\n\nמרכיבים לבצק:\n- 500 גרם קמח לבן (ניתן להשתמש בקמח חיטה מלאה או תערובת של שניהם)\n- 300 מ\"ל מים פושרים\n- 10 גרם שמרים יבשים\n- כף שטוחה מלח\n- כף שטוחה סוכר\n- 3 כפות שמן זית\n\nמרכיבים לרוטב:\n- 1 קופסת רסק עגבניות\n- 2 שיניים שום כתושות\n- כפית אורגנו יבש\n- כפית בזיליקום יבש\n- מלח ופלפל לפי הטעם\n\nתוספות לפיצה:\n- גבינת מוצרלה מגוררת\n- תוספות לבחירה כגון: פטריות, זיתים, בצל, פלפלים, נקניקיות ועוד.\n\nאופן ההכנה:\n1. מכינים את הבצק: מערבבים את השמרים עם הסוכר והמים וממתינים כ-10 דקות עד שהשמרים מתחילים לפעול. לאחר מכן מוסיפים את הקמח, המלח והשמן ולשים עד לקבלת בצק חלק ואחיד. מניחים את הבצק לתפוח במקום חמים למשך שעה.\n2. מכינים את הרוטב: מערבבים את רסק העגבניות עם השום, האורגנו, הבזיליקום, המלח והפלפל.\n3. מחממים תנור ל-220 מעלות צלזיוס.\n4. פורסים את הבצק לעיגול בעזרת מערוך או ידיים משומנות ומניחים על תבנית פיצה.\n5. מורחים את הרוטב על הבצק, מפזרים את הגבינה והתוספות לבחירה.\n6. אופים במשך כ-15-20 דקות או עד שהפיצה מזהיבה והגבינה מתקרמלת.\n\nתהנו!", "type": "text"}]}'::jsonb, 26752, '2025-05-18T08:07:24.320851'::timestamptz),
