    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'qs2teW8SxknI-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'qs2teW8SxknI-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "הכנת הפיצה הדיאטית עם בצק קוליפלואר כוללת מספר שלבים והזמנים הם כדלקמן:\n\n1. הכנת הבצק: כ-10 דקות לטחון את הקוליפלואר ולערבב אותו עם המרכיבים הנוספים.\n2. אפיית הבצק: כ-15 דקות בתנור שחומם מראש ל-200 מעלות צלזיוס.\n3. הכנת הרוטב: כ-5 דקות לערבב את כל מרכיבי הרוטב.\n4. הרכבת הפיצה עם הרוטב והתוספות: כ-5 דקות.\n5. אפיית הפיצה המורכבת: כ-10 דקות נוספות בתנור.\n\nבסך הכל, הכנת הפיצה תיקח כ-45 דקות מתחילת העבודה ועד שהיא מוכנה להגשה. זמן זה כולל הכנה, אפייה והרכבה של הפיצה.", "type": "text"}]}'::jsonb, 15477, '2025-05-18T08:11:14.550205'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'pWPg1BiOTjCu-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'pWPg1BiOTjCu-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "אני רוצה סלט עם זיתים", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-18T08:16:30.411566'::timestamptz - interval '1 second'),
