    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '5OART9aMiluc-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '5OART9aMiluc-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "תלמד אותי על פקודות git", "type": "text"}]}'::jsonb, NULL::integer, '2026-04-12T08:15:05.426490'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '5OART9aMiluc-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '5OART9aMiluc-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "כמובן! Git הוא כלי לשליטה ובקרה בגרסאות של קוד, פופולרי במיוחד בפיתוח תוכנה. הנה סקירה קצרה על פקודות Git בסיסיות:\n\n1. **git init**: פקודה זו יוצרת מאגר חדש של Git בספרייה בה אתה נמצא. זה מתחיל לעקוב אחר קבצים ושינויים.\n\n2. **git clone [url]**: משכפל מאגר Git מרוחק למחשב המקומי שלך. כתובת ה-URL מציינת את מיקום המאגר המרוחק.\n\n3. **git add [file]**: מוסיפה קובץ או קבצים מסוימים למעקב (staging area). אפשר להשתמש ב־`.` כדי להוסיף את כל הקבצים.\n\n4. **git commit -m \"message\"**: שומר את השינויים שבוצעו בקבצים שהוספת ובעצם יוצר נקודת שחזור. חשוב לכתוב הודעת commit ברורה.\n\n5. **git status**: מציג את הסטטוס הנוכחי של המאגר שלך, כולל אילו קבצים שונו, נוספו או הומרו ל־commit.\n\n6. **git log**: מראה את היסטוריית ה־commits של המאגר, כך שתוכל לראות מי עשה אילו שינויים ומתי.\n\n7. **git branch**: מציג את כל הסניפים הנוכחיים. אפשר גם להשתמש ב־git branch [branch-name] כדי ליצור סניף חדש.\n\n8. **git checkout [branch-name]**: עובר בין סניפים שונים במאגר. אפשר גם להשתמש ב-checkout כדי לשחזר קבצים למצבן האחרון.\n\n9. **git merge [branch-name]**: משלב את השינויים מסניף אחד לאחר. לרוב משתמשים בו כדי לשלב שינויים חזרה לסניף הראשי (main/master).\n\n10. **git pull**: מושך שינויים מהמאגרים המרוחקים למאגר המקומי שלך.\n\n11. **git push**: דוחף את השינויים המותחילים (committed) שלך למאגר מרוחק.\n\nכלי Git יכול להיות מורכב בהתחלה, אבל עם הזמן והשימוש תהפוך להיות יותר מיומן בו. אם תרצה הסבר נוסף על פקודה מסוימת או נושא מתקדם יותר, אנא יידע אותי!", "type": "text"}]}'::jsonb, 6532, '2026-04-12T08:15:05.426490'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'PYuOgMQsYQlj-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'PYuOgMQsYQlj-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "סכם את הרעיונות לסוכנים שעלו בפגישה", "type": "text"}]}'::jsonb, NULL::integer, '2025-07-31T07:54:00.715954'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'PYuOgMQsYQlj-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'PYuOgMQsYQlj-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "Several ideas for agents emerged during the meeting, including the development of a dedicated document comparison agent for task management using SAP and possible connections to a BI or SAP solution. Additionally, there were discussions on automating inventory management and safety processes, incorporating smart systems for maintenance reminders, and digitalizing safety documents. In the rotary equipment team, there is potential for an AI agent to detect fault patterns and automatically interpret vibration analyses from FFT measurements, with outputs providing recommendations for station management.", "type": "text"}]}'::jsonb, 3231, '2025-07-31T07:54:00.715954'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'b2kPN27zu5lW-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'b2kPN27zu5lW-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "מה התפקיד של   buddy בשבוע הראשון ", "type": "text"}]}'::jsonb, NULL::integer, '2026-04-12T08:31:34.911181'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'b2kPN27zu5lW-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'b2kPN27zu5lW-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "בשבוע הראשון, ה-Buddy מומלץ להיות נוכח יותר ולבדוק על בסיס יומי איך הדברים מתקדמים עבור העובד החדש. עליו להגיד שלום ולהציג את עצמו ביום הראשון, לקבוע שיחת היכרות קצרה, לעזור בהבנה על הצוות והאנשים, ליזום ארוחות צהריים משותפות והפסקות קפה, ולהיות זמין לשאלות קטנות שעולות במהלך היום.", "type": "text"}]}'::jsonb, 2490, '2026-04-12T08:31:34.911181'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'hVGfQ2UCqKPa-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'hVGfQ2UCqKPa-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "מה כתוב בשורה הראשונה?", "type": "text"}]}'::jsonb, NULL::integer, '2025-12-25T14:25:20.615408'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'hVGfQ2UCqKPa-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'hVGfQ2UCqKPa-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "השורה הראשונה של מערך הנתונים מכילה את המידע הבא:\n\n- **Table:** jeen_dev_bot_prompts_default_value\n- **Column:** content\n- **ID - if have:** analysisPrompt\n- **Prompt:** Analyze according to the conversation and what the user wrote, what are the features of the answer the user is looking for. Carefully consider all user messages and preferences in your analysis. Each time the user mentions a new preference, consider the previous messages they have written and include all their messages integrated into your analysis. Analyze according to what the user wrote, consider all the users messages from the beginning of the conversation, what are the features of the answer the user is looking for. Mention this in your comment. Response format: User Wants: [One sentence in English] Example responses: User Wants: The safety instructions. User Wants: The maintenance required for the new project. User Wants: to delete a contact in the app. User Wants: Details on opening a new account.\n- **Is in app code:** YES\n- **מה המטרה?** לנתח את רצון המשתמש מההודעה\n- **מה מצפים לקבל?** user wants: A sentence in English that best describes the users desire", "type": "text"}]}'::jsonb, 8728, '2025-12-25T14:25:20.615408'::timestamptz),
