    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'QqfdDQaFNnSD-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'QqfdDQaFNnSD-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "מה קורה?", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-15T12:15:33.916876'::timestamptz - interval '1 second'),
