    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '8uHnfV5WrxnT-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '8uHnfV5WrxnT-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "כתוב לי מייל", "type": "text"}]}'::jsonb, NULL::integer, '2025-09-22T07:22:22.048181'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '8uHnfV5WrxnT-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '8uHnfV5WrxnT-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "כמובן! הנה דוגמה למייל שאפשר להשתמש בו:\n\n---\n\nSubject: בקשה לפגישה\n\nשלום [שם נמען],\n\nאני מקווה שהמייל הזה מוצא אותך בטוב. רציתי לבדוק אם תוכל לפנות זמן לשיחה קצרה בשבוע הבא בנוגע ל[נושא השיחה]. אני מאמין ששיחה זו יכולה להיות מועילה לשנינו ואשמח לשמוע את דעתך.\n\nהאם יש תאריך או שעה שמתאימים לך במיוחד?\n\nתודה רבה מראש על תשומת הלב שלך, ואני מצפה לשמוע ממך!\n\nבברכה,  \n[שמך]\n\n---\n\nאם יש פרטים נוספים שתרצה לכלול, כמו תאריך, שעה, או פרטים נוספים, אל תהסס לעדכן אותי ואני אשמח להתאים את המייל עבורך!", "type": "text"}]}'::jsonb, 1, '2025-09-22T07:22:22.048181'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'xz2sBUQwt4x2-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'xz2sBUQwt4x2-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "אני רוצה לכתוב הודעה למועמד שלא עבר את הראיון", "type": "text"}]}'::jsonb, NULL::integer, '2025-09-22T07:22:43.902390'::timestamptz - interval '1 second'),
