    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'alxQVmfbQB8t-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'alxQVmfbQB8t-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "אליהו הנביא הוא דמות מקראית חשובה במסורת היהודית, הנוצרית והמוסלמית. הוא היה נביא שפעל בממלכת ישראל בתקופת המלך אחאב, במאה ה-9 לפני הספירה. אליהו נודע בנחישותו להחזיר את עם ישראל לעבודת ה ולמנוע את עבודת האלילים, במיוחד פולחן הבעל, שהופץ על ידי איזבל, אשתו של אחאב.\n\nבין הסיפורים הידועים על אליהו ניתן למצוא את מעמד הר הכרמל, בו התמודד כנגד נביאי הבעל והוכיח את אמיתות אמונתו ב- אלוהים. מסורות מאוחרות יותר מייחסות לאליהו תפקיד של מבשר הגאולה העתידית והוא מוזכר בהגדה של פסח ובטקסים אחרים ביהדות. במקרא, על פי הסיפור, אליהו לא מת מוות טבעי אלא עלה בסערה השמיימה, וזה הפך אותו לסמל נצחי בעולם היהודי והמסורות האחרות.", "type": "text"}]}'::jsonb, 4784, '2026-04-26T11:55:30.505708'::timestamptz),
