    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 's7ALfF6amhHy-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 's7ALfF6amhHy-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "המרחק בין פתח תקווה לירושלים הוא כ-60 קילומטרים (כ-37 מייל) כאשר נוסעים ברכב, תלוי במסלול הנסיעה המדויק. זמן הנסיעה המשוער יכול לנוע בין 45 דקות לשעה וחצי, בהתאם לתנאי התנועה ולמסלול הנבחר.", "type": "text"}]}'::jsonb, 2630, '2026-04-26T11:55:49.716420'::timestamptz),
