    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'asYd9dhnFDUp-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'asYd9dhnFDUp-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "הוספתי כותרת למסמך אפיון", "type": "text"}]}'::jsonb, 1877, '2025-05-29T07:06:17.478208'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'xqNHijsO3aXK-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'xqNHijsO3aXK-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "Add this registry keys and create the full script to download :\r\n\r\nreg add \"HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System\" /v EnableFirstLogonAnimation /t REG_DWORD /d 0 /f\r\nreg add \"HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows\\OOBE\" /v DisablePrivacyExperience /t REG_DWORD /d 1 /f\r\nreg add \"HKLM\\SOFTWARE\\Microsoft\\Provisioning\\Diagnostics\\Autopilot\" /v DisableEnrollmentStatusPage /t REG_DWORD /d 1 /f\r\n\r\n\r\nimport subprocess\r\nimport os\r\nimport winreg\r\nimport time\r\nimport psutil\r\nfrom datetime import datetime\r\n\r\n# PowerShell script to create or update local user\r\nSCRIPT_USER_MANAGEMENT = \"\"\"\r\n$username = \"ortest\"\r\n$password = ConvertTo-SecureString \"Passw0rd\" -AsPlainText -Force\r\n\r\n# Check if user exists\r\n$userExists = Get-LocalUser | Where-Object {$_.Name -eq $username}\r\n\r\nif ($userExists) {\r\n    Set-LocalUser -Name $username -Password $password\r\n    Write-Host \"User $username already exists. Password updated.\"\r\n} else {\r\n    New-LocalUser -Name $username -Password $password -FullName \"IT Lab User\" -Description \"IT Lab Administrator Account\" -PasswordNeverExpires\r\n    Write-Host \"User $username created successfully.\"\r\n}\r\n\"\"\"\r\n\r\n# PowerShell script to disable all network adapters (simulating Airplane Mode)\r\nSCRIPT_DISABLE_NETWORK = \"\"\"\r\nWrite-Host \"Disabling all network adapters (simulating Airplane Mode)...\"\r\nGet-NetAdapter | Where-Object {$_.Status -eq Up} | Disable-NetAdapter -Confirm:$false\r\nWrite-Host \"All network adapters have been disabled.\"\r\n\"\"\"\r\n\r\n# PowerShell script to enable all network adapters\r\nSCRIPT_ENABLE_NETWORK = \"\"\"\r\nWrite-Host \"Enabling all network adapters (reverting from Airplane Mode)...\"\r\nGet-NetAdapter | Where-Object {$_.Status -eq Disabled} | Enable-NetAdapter -Confirm:$false\r\nWrite-Host \"All network adapters have been enabled.\"\r\n\"\"\"\r\n\r\n# MBAM uninstall\r\nSCRIPT_1_MBAM = \"\"\"\r\n$mbam = Get-ItemProperty HKLM:\\\\Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Uninstall\\\\* |\r\n    Where-Object { $_.DisplayName -like \"*MBAM*\" }\r\nif ($mbam) {\r\n    $uninstallCmd = $mbam.UninstallString -replace \"msiexec.exe\", \"\"\r\n    Start-Process \"msiexec.exe\" -ArgumentList \"$($uninstallCmd) /quiet /norestart\" -Wait\r\n    Write-Host \"MBAM Client uninstalled.\"\r\n} else {\r\n    Write-Host \"MBAM not found on this system.\"\r\n}\r\n\"\"\"\r\n\r\n# LAPS uninstall\r\nSCRIPT_2_LAPS = \"\"\"\r\nGet-ChildItem -Path \"HKLM:SOFTWARE\\\\wow6432node\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Uninstall\",\"HKLM:SOFTWARE\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Uninstall\" -Recurse |   \r\nWhere {$_.GetValue(\"DisplayName\") -like \"*Local Administrator Password Solution*\"} |   \r\nForEach-Object {  \r\n    $DisplayName = $_.GetValue(\"DisplayName\")\r\n    $DisplayVersion = $_.GetValue(\"DisplayVersion\")   \r\n    $UninstallString = $_.GetValue(\"UninstallString\")\r\n}\r\n$productCode = $UninstallString -replace (\"msiexec.exe /I\",\"\")\r\nStart-Process -FilePath \"msiexec.exe\" -ArgumentList \"/x $productCode /quiet /norestart\" -Wait -PassThru\r\n\"\"\"\r\n\r\n# SCCM uninstall and cleanup\r\nSCRIPT_3_SCCM = \"\"\"\r\nfunction uninstallSCCM() {\r\n    if (Test-Path -Path \"$Env:SystemDrive\\\\Windows\\\\ccmsetup\\\\ccmsetup.exe\") {\r\n        Get-Service -Name CcmExec -ErrorAction SilentlyContinue | Stop-Service -Force -Verbose\r\n        Get-Service -Name ccmsetup -ErrorAction SilentlyContinue | Stop-Service -Force -Verbose\r\n        Start-Process -FilePath \"$Env:SystemDrive\\\\Windows\\\\ccmsetup\\\\ccmsetup.exe\" -ArgumentList /uninstall\r\n        do {\r\n            Start-Sleep -Milliseconds 1000\r\n            $Process = (Get-Process ccmsetup -ErrorAction SilentlyContinue)\r\n        } until ($null -eq $Process)\r\n        Write-Host \"SCCM uninstallation completed\"\r\n    }\r\n}\r\nfunction removeSCCM() {\r\n    Get-Service -Name CcmExec -ErrorAction SilentlyContinue | Stop-Service -Force -Verbose\r\n    Get-Service -Name ccmsetup -ErrorAction SilentlyContinue | Stop-Service -Force -Verbose\r\n    $null = takeown /F \"$($Env:WinDir)\\\\CCM\" /R /A /D Y 2>&1\r\n    Remove-Item -Path \"$($Env:WinDir)\\\\CCM\" -Force -Recurse -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    $null = takeown /F \"$($Env:WinDir)\\\\CCMSetup\" /R /A /D Y 2>&1\r\n    Remove-Item -Path \"$($Env:WinDir)\\\\CCMSetup\" -Force -Recurse -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    $null = takeown /F \"$($Env:WinDir)\\\\CCMCache\" /R /A /D Y 2>&1\r\n    Remove-Item -Path \"$($Env:WinDir)\\\\CCMCache\" -Force -Recurse -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path \"$($Env:WinDir)\\\\smscfg.ini\" -Force -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\Software\\\\Microsoft\\\\SystemCertificates\\\\SMS\\\\Certificates\\\\* -Force -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\SOFTWARE\\\\Microsoft\\\\CCM -Force -Recurse -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\SOFTWARE\\\\Wow6432Node\\\\Microsoft\\\\CCM -Force -Recurse -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\SOFTWARE\\\\Microsoft\\\\SMS -Force -Recurse -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\SOFTWARE\\\\Wow6432Node\\\\Microsoft\\\\SMS -Force -Recurse -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\Software\\\\Microsoft\\\\CCMSetup -Force -Recurse -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\Software\\\\Wow6432Node\\\\Microsoft\\\\CCMSetup -Force -Confirm:$false -Recurse -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\SYSTEM\\\\CurrentControlSet\\\\Services\\\\CcmExec -Force -Recurse -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    Remove-Item -Path HKLM:\\\\SYSTEM\\\\CurrentControlSet\\\\Services\\\\ccmsetup -Force -Recurse -Confirm:$false -Verbose -ErrorAction SilentlyContinue\r\n    Get-CimInstance -Query \"Select * From __Namespace Where Name=CCM\" -Namespace \"root\" -ErrorAction SilentlyContinue | Remove-CimInstance -Verbose -Confirm:$false -ErrorAction SilentlyContinue\r\n    Get-CimInstance -Query \"Select * From __Namespace Where Name=CCMVDI\" -Namespace \"root\" -ErrorAction SilentlyContinue | Remove-CimInstance -Verbose -Confirm:$false -ErrorAction SilentlyContinue\r\n    Get-CimInstance -Query \"Select * From __Namespace Where Name=SmsDm\" -Namespace \"root\" -ErrorAction SilentlyContinue | Remove-CimInstance -Verbose -Confirm:$false -ErrorAction SilentlyContinue\r\n    Get-CimInstance -Query \"Select * From __Namespace Where Name=sms\" -Namespace \"root\\\\cimv2\" -ErrorAction SilentlyContinue | Remove-CimInstance -Verbose -Confirm:$false -ErrorAction SilentlyContinue\r\n    Write-Host \"All traces of SCCM have been removed\"\r\n}\r\nuninstallSCCM\r\nremoveSCCM\r\n\"\"\"\r\n\r\n# Remove from domain and join workgroup (ORMWG)\r\nSCRIPT_REMOVE_DOMAIN = \"\"\"\r\n$computerSystem = Get-WmiObject Win32_ComputerSystem\r\nif ($computerSystem.PartOfDomain -eq $true) {\r\n    Write-Host \"Computer is currently joined to domain: $($computerSystem.Domain)\"\r\n    Write-Host \"Removing computer from domain and joining workgroup ORMWG...\"\r\n    $username = \"itlab\"\r\n    $password = ConvertTo-SecureString \"Ormat1965!\" -AsPlainText -Force\r\n    $credential = New-Object System.Management.Automation.PSCredential($username, $password)\r\n    try {\r\n        Remove-Computer -WorkgroupName \"ORMWG\" -Force -Restart:$false -PassThru -Verbose\r\n        Write-Host \"Successfully removed from domain and joined workgroup ORMWG\"\r\n        Write-Host \"Computer will need to be restarted for changes to take effect.\"\r\n    } catch {\r\n        Write-Host \"Error: $_\"\r\n        Write-Host \"Attempting alternative method without credentials...\"\r\n        $domainUsername = $env:USERNAME\r\n        $domainPassword = Read-Host \"Enter domain admin password\" -AsSecureString\r\n        $domainCred = New-Object System.Management.Automation.PSCredential($env:USERDOMAIN + \"\\\\\" + $domainUsername, $domainPassword)\r\n        Remove-Computer -UnjoinDomainCredential $domainCred -WorkgroupName \"or\" -Force -Restart:$false -PassThru -Verbose\r\n    }\r\n} else {\r\n    Write-Host \"Computer is not part of a domain. Current workgroup: $($computerSystem.Domain)\"\r\n    if ($computerSystem.Domain -ne \"ORMWG\") {\r\n        Write-Host \"Changing workgroup to ORMWG...\"\r\n        Add-Computer -WorkgroupName \"ORMWG\" -Force\r\n        Write-Host \"Workgroup changed to ORMWG\"\r\n    } else {\r\n        Write-Host \"Computer is already in workgroup ORMWG\"\r\n    }\r\n}\r\n\"\"\"\r\n\r\n# Remove Windows Hello Container\r\nSCRIPT_REMOVE_HELLO = r& \"C:\\Windows\\SysWOW64\\certutil.exe\" -DeleteHelloContainer\r\n\r\n\r\nclass UninstallVerifier:\r\n    def __init__(self, max_retries=5, retry_delay=30):\r\n        self.log_file = f\"uninstall_verification_{datetime.now().strftime(%Y%m%d_%H%M%S)}.log\"\r\n        self.max_retries = max_retries\r\n        self.retry_delay = retry_delay\r\n        \r\n    def log(self, message):\r\n        print(message)\r\n        with open(self.log_file, a, encoding=utf-8) as f:\r\n            f.write(f\"{datetime.now().strftime(%Y-%m-%d %H:%M:%S)} - {message}\\n\")\r\n    \r\n    def run_powershell_script(self, script, script_name):\r\n        self.log(f\"\\n{=*60}\")\r\n        self.log(f\"Running {script_name}...\")\r\n        self.log(f\"{=*60}\")\r\n        try:\r\n            result = subprocess.run(\r\n                [\"powershell\", \"-ExecutionPolicy\", \"Bypass\", \"-Command\", script],\r\n                capture_output=True,\r\n                text=True,\r\n                timeout=300\r\n            )\r\n            if result.stdout:\r\n                self.log(f\"Output:\\n{result.stdout}\")\r\n            if result.stderr:\r\n                self.log(f\"Errors:\\n{result.stderr}\")\r\n            self.log(f\"Return code: {result.returncode}\")\r\n            return result.returncode == 0\r\n        except subprocess.TimeoutExpired:\r\n            self.log(f\"ERROR: {script_name} timed out after 5 minutes\")\r\n            return False\r\n        except Exception as e:\r\n            self.log(f\"ERROR running {script_name}: {str(e)}\")\r\n            return False\r\n\r\n    def check_registry_key_exists(self, hive, key_path, value_name=None):\r\n        try:\r\n            key = winreg.OpenKey(hive, key_path, 0, winreg.KEY_READ | winreg.KEY_WOW64_64KEY)\r\n            if value_name:\r\n                winreg.QueryValueEx(key, value_name)\r\n            winreg.CloseKey(key)\r\n            return True\r\n        except FileNotFoundError:\r\n            return False\r\n        except Exception:\r\n            return False\r\n\r\n    def check_application_in_registry(self, app_pattern):\r\n        uninstall_paths = [\r\n            r\"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\",\r\n            r\"SOFTWARE\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\"\r\n        ]\r\n        found = []\r\n        for path in uninstall_paths:\r\n            try:\r\n                key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, path, 0, winreg.KEY_READ | winreg.KEY_WOW64_64KEY)\r\n                i = 0\r\n                while True:\r\n                    try:\r\n                        subkey_name = winreg.EnumKey(key, i)\r\n                        subkey = winreg.OpenKey(key, subkey_name)\r\n                        try:\r\n                            display_name, _ = winreg.QueryValueEx(subkey, \"DisplayName\")\r\n                            if app_pattern.lower() in display_name.lower():\r\n                                found.append(display_name)\r\n                        except FileNotFoundError:\r\n                            pass\r\n                        winreg.CloseKey(subkey)\r\n                        i += 1\r\n                    except OSError:\r\n                        break\r\n                winreg.CloseKey(key)\r\n            except Exception:\r\n                pass\r\n        return found\r\n\r\n    def check_service_exists(self, service_name):\r\n        try:\r\n            service = psutil.win_service_get(service_name)\r\n            return True\r\n        except Exception:\r\n            return False\r\n\r\n    def check_path_exists(self, path):\r\n        return os.path.exists(path)\r\n    \r\n    def check_local_user_exists(self, username):\r\n        self.log(f\"Checking if user {username} exists...\")\r\n        check_script = f\"\"\"\r\n        $user = Get-LocalUser | Where-Object {{$_.Name -eq \"{username}\"}}\r\n        if ($user) {{\r\n            Write-Host \"User exists\"\r\n            exit 0\r\n        }} else {{\r\n            Write-Host \"User does not exist\"\r\n            exit 1\r\n        }}\r\n        \"\"\"\r\n        try:\r\n            result = subprocess.run(\r\n                [\"powershell\", \"-ExecutionPolicy\", \"Bypass\", \"-Command\", check_script],\r\n                capture_output=True,\r\n                text=True,\r\n                timeout=30\r\n            )\r\n            exists = result.returncode == 0\r\n            self.log(f\"User {username} exists: {exists}\")\r\n            return exists\r\n        except Exception as e:\r\n            self.log(f\"ERROR checking if user exists: {str(e)}\")\r\n            return False\r\n\r\n    def check_domain_status(self):\r\n        self.log(\"Checking domain/workgroup status...\")\r\n        check_script = \"\"\"\r\n        $computerSystem = Get-WmiObject Win32_ComputerSystem\r\n        if ($computerSystem.PartOfDomain) {\r\n            Write-Host \"DOMAIN:$($computerSystem.Domain)\"\r\n        } else {\r\n            Write-Host \"WORKGROUP:$($computerSystem.Domain)\"\r\n        }\r\n        \"\"\"\r\n        try:\r\n            result = subprocess.run(\r\n                [\"powershell\", \"-ExecutionPolicy\", \"Bypass\", \"-Command\", check_script],\r\n                capture_output=True,\r\n                text=True,\r\n                timeout=30\r\n            )\r\n            output = result.stdout.strip()\r\n            self.log(f\"Current status: {output}\")\r\n            if \"WORKGROUP:or\" in output:\r\n                return True, \"workgroup_or\"\r\n            elif \"WORKGROUP:\" in output:\r\n                return False, \"workgroup_other\"\r\n            else:\r\n                return False, \"domain\"\r\n        except Exception as e:\r\n            self.log(f\"ERROR checking domain status: {str(e)}\")\r\n            return False, \"unknown\"\r\n\r\n    def disable_network_adapters(self):\r\n        self.log(\"\\n\" + \"=\"*60)\r\n        self.log(\"Disabling Network Adapters\")\r\n        self.log(\"=\"*60)\r\n        success = self.run_powershell_script(SCRIPT_DISABLE_NETWORK, \"Disable Network Adapters Script\")\r\n        if success:\r\n            self.log(\"[OK] All network adapters have been disabled\")\r\n            return True\r\n        else:\r\n            self.log(\"[WARN] Failed to disable network adapters\")\r\n            return False\r\n\r\n    def enable_network_adapters(self):\r\n        self.log(\"\\n\" + \"=\"*60)\r\n        self.log(\"Enabling Network Adapters\")\r\n        self.log(\"=\"*60)\r\n        success = self.run_powershell_script(SCRIPT_ENABLE_NETWORK, \"Enable Network Adapters Script\")\r\n        if success:\r\n            self.log(\"[OK] All network adapters have been enabled\")\r\n            return True\r\n        else:\r\n            self.log(\"[WARN] Failed to enable network adapters\")\r\n            return False\r\n\r\n    def manage_local_user(self):\r\n        self.log(\"\\n\" + \"=\"*60)\r\n        self.log(\"Managing Local User Account\")\r\n        self.log(\"=\"*60)\r\n        success = self.run_powershell_script(SCRIPT_USER_MANAGEMENT, \"User Management Script\")\r\n        if success:\r\n            if self.check_local_user_exists(\"itlab\"):\r\n                self.log(\"[OK] User itlab successfully created/updated\")\r\n                return True\r\n            else:\r\n                self.log(\"[FAIL] User itlab verification failed\")\r\n                return False\r\n        else:\r\n            self.log(\"[FAIL] User management script failed\")\r\n            return False\r\n\r\n    def remove_from_domain(self):\r\n        self.log(\"\\n\" + \"=\"*60)\r\n        self.log(\"Removing Computer from Domain\")\r\n        self.log(\"=\"*60)\r\n        is_correct, status = self.check_domain_status()\r\n        if is_correct:\r\n            self.log(\"[OK] Computer is already in workgroup or\")\r\n            return True\r\n        success = self.run_powershell_script(SCRIPT_REMOVE_DOMAIN, \"Domain Removal Script\")\r\n        if success:\r\n            time.sleep(5)\r\n            is_correct, status = self.check_domain_status()\r\n            if is_correct or status == \"workgroup_or\":\r\n                self.log(\"[OK] Computer successfully removed from domain and joined workgroup or\")\r\n                self.log(\"[INFO] NOTE: Computer must be restarted for changes to take full effect\")\r\n                return True\r\n            else:\r\n                self.log(f\"[WARN] Computer status changed but not in workgroup or. Current: {status}\")\r\n                return False\r\n        else:\r\n            self.log(\"[FAIL] Domain removal script failed\")\r\n            return False\r\n\r\n    def verify_mbam_uninstalled(self):\r\n        self.log(\"\\n--- Verifying MBAM Uninstallation ---\")\r\n        mbam_apps = self.check_application_in_registry(\"MBAM\")\r\n        if mbam_apps:\r\n            self.log(f\"FAILED: MBAM still found in registry: {mbam_apps}\")\r\n            return False\r\n        else:\r\n            self.log(\"PASSED: MBAM not found in registry\")\r\n        mbam_paths = [\r\n            r\"C:\\Program Files\\Microsoft\\MDOP MBAM\",\r\n            r\"C:\\Program Files (x86)\\Microsoft\\MDOP MBAM\"\r\n        ]\r\n        paths_exist = [p for p in mbam_paths if self.check_path_exists(p)]\r\n        if paths_exist:\r\n            self.log(f\"FAILED: MBAM directories still exist: {paths_exist}\")\r\n            return False\r\n        else:\r\n            self.log(\"PASSED: MBAM directories not found\")\r\n        self.log(\"SUCCESS: MBAM is fully uninstalled\")\r\n        return True\r\n\r\n    def verify_laps_uninstalled(self):\r\n        self.log(\"\\n--- Verifying LAPS Uninstallation ---\")\r\n        laps_apps = self.check_application_in_registry(\"Local Administrator Password Solution\")\r\n        if laps_apps:\r\n            self.log(f\"FAILED: LAPS still found in registry: {laps_apps}\")\r\n            return False\r\n        else:\r\n            self.log(\"PASSED: LAPS not found in registry\")\r\n        laps_reg_keys = [\r\n            (winreg.HKEY_LOCAL_MACHINE, r\"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\LAPS\"),\r\n            (winreg.HKEY_LOCAL_MACHINE, r\"SOFTWARE\\Policies\\Microsoft Services\\AdmPwd\")\r\n        ]\r\n        keys_exist = []\r\n        for hive, key in laps_reg_keys:\r\n            if self.check_registry_key_exists(hive, key):\r\n                keys_exist.append(key)\r\n        if keys_exist:\r\n            self.log(f\"WARNING: LAPS registry keys still exist: {keys_exist}\")\r\n        else:\r\n            self.log(\"PASSED: LAPS registry keys not found\")\r\n        laps_paths = [\r\n            r\"C:\\Program Files\\LAPS\",\r\n            r\"C:\\Program Files (x86)\\LAPS\"\r\n        ]\r\n        paths_exist = [p for p in laps_paths if self.check_path_exists(p)]\r\n        if paths_exist:\r\n            self.log(f\"FAILED: LAPS directories still exist: {paths_exist}\")\r\n            return False\r\n        else:\r\n            self.log(\"PASSED: LAPS directories not found\")\r\n        self.log(\"SUCCESS: LAPS is fully uninstalled\")\r\n        return True\r\n\r\n    def verify_sccm_uninstalled(self):\r\n        self.log(\"\\n--- Verifying SCCM Uninstallation ---\")\r\n        sccm_services = [\"CcmExec\", \"ccmsetup\"]\r\n        services_exist = [s for s in sccm_services if self.check_service_exists(s)]\r\n        if services_exist:\r\n            self.log(f\"FAILED: SCCM services still exist: {services_exist}\")\r\n            return False\r\n        else:\r\n            self.log(\"PASSED: SCCM services not found\")\r\n        sccm_reg_keys = [\r\n            r\"SOFTWARE\\Microsoft\\CCM\",\r\n            r\"SOFTWARE\\Wow6432Node\\Microsoft\\CCM\",\r\n            r\"SOFTWARE\\Microsoft\\SMS\",\r\n            r\"SOFTWARE\\Wow6432Node\\Microsoft\\SMS\",\r\n            r\"Software\\Microsoft\\CCMSetup\",\r\n            r\"Software\\Wow6432Node\\Microsoft\\CCMSetup\",\r\n            r\"SYSTEM\\CurrentControlSet\\Services\\CcmExec\",\r\n            r\"SYSTEM\\CurrentControlSet\\Services\\ccmsetup\"\r\n        ]\r\n        keys_exist = []\r\n        for key in sccm_reg_keys:\r\n            if self.check_registry_key_exists(winreg.HKEY_LOCAL_MACHINE, key):\r\n                keys_exist.append(key)\r\n        if keys_exist:\r\n            self.log(f\"FAILED: SCCM registry keys still exist: {keys_exist}\")\r\n            return False\r\n        else:\r\n            self.log(\"PASSED: SCCM registry keys not found\")\r\n        win_dir = os.environ.get(\"WINDIR\", r\"C:\\Windows\")\r\n        sccm_paths = [\r\n            os.path.join(win_dir, \"CCM\"),\r\n            os.path.join(win_dir, \"CCMSetup\"),\r\n            os.path.join(win_dir, \"CCMCache\"),\r\n            os.path.join(win_dir, \"smscfg.ini\")\r\n        ]\r\n        paths_exist = [p for p in sccm_paths if self.check_path_exists(p)]\r\n        if paths_exist:\r\n            self.log(f\"FAILED: SCCM files/directories still exist: {paths_exist}\")\r\n            return False\r\n        else:\r\n            self.log(\"PASSED: SCCM directories and files not found\")\r\n        self.log(\"SUCCESS: SCCM is fully uninstalled\")\r\n        return True\r\n\r\n    def uninstall_with_retry(self, script, script_name, verify_func):\r\n        attempt = 0\r\n        while attempt < self.max_retries:\r\n            attempt += 1\r\n            self.log(f\"\\n{#*60}\")\r\n            self.log(f\"Attempt {attempt}/{self.max_retries} for {script_name}\")\r\n            self.log(f\"{#*60}\")\r\n            self.run_powershell_script(script, script_name)\r\n            wait_time = 10 if \"SCCM\" not in script_name else 20\r\n            self.log(f\"Waiting {wait_time} seconds for uninstallation to complete...\")\r\n            time.sleep(wait_time)\r\n            if verify_func():\r\n                self.log(f\"[OK] {script_name} successfully uninstalled and verified\")\r\n                return True\r\n            else:\r\n                if attempt < self.max_retries:\r\n                    self.log(f\"[WARN] Verification failed. Retrying in {self.retry_delay} seconds...\")\r\n                    time.sleep(self.retry_delay)\r\n                else:\r\n                    self.log(f\"[FAIL] {script_name} failed after {self.max_retries} attempts\")\r\n                    return False\r\n        return False\r\n\r\n    def run_all(self):\r\n        self.log(\"=\"*60)\r\n        self.log(\"Starting Uninstallation and Verification Process\")\r\n        self.log(f\"Max Retries: {self.max_retries}\")\r\n        self.log(f\"Retry Delay: {self.retry_delay} seconds\")\r\n        self.log(f\"Log file: {self.log_file}\")\r\n        self.log(\"=\"*60)\r\n        results = {}\r\n\r\n        # Step 1: Manage local user account (create/update itlab user)\r\n        results[User Management] = self.manage_local_user()\r\n\r\n        # Step 2: Disable all network adapters (simulating Airplane Mode)\r\n        results[Disable Network Adapters] = self.disable_network_adapters()\r\n\r\n        # Step 3: MBAM uninstall with retry\r\n        results[MBAM] = self.uninstall_with_retry(\r\n            SCRIPT_1_MBAM, \r\n            \"MBAM Uninstall Script\", \r\n            self.verify_mbam_uninstalled\r\n        )\r\n\r\n        # Step 4: LAPS uninstall with retry\r\n        results[LAPS] = self.uninstall_with_retry(\r\n            SCRIPT_2_LAPS, \r\n            \"LAPS Uninstall Script\", \r\n            self.verify_laps_uninstalled\r\n        )\r\n\r\n        # Step 5: SCCM uninstall with retry\r\n        results[SCCM] = self.uninstall_with_retry(\r\n            SCRIPT_3_SCCM, \r\n            \"SCCM Uninstall Script\", \r\n            self.verify_sccm_uninstalled\r\n        )\r\n\r\n        # Step 6: Remove from domain and join workgroup or\r\n        results[Domain Removal] = self.remove_from_domain()\r\n\r\n        # Step 7: Enable all network adapters (reverting from Airplane Mode)\r\n        results[Enable Network Adapters] = self.enable_network_adapters()\r\n\r\n        # Step 8: Remove Windows Hello\r\n        self.log(\"\\n\" + \"=\"*60)\r\n        self.log(\"Removing Windows Hello Container\")\r\n        self.log(\"=\"*60)\r\n        result_hello = self.run_powershell_script(SCRIPT_REMOVE_HELLO, \"Remove Windows Hello Container Script\")\r\n        results[Remove Windows Hello] = result_hello\r\n        if result_hello:\r\n            self.log(\"[OK] Windows Hello container removed.\")\r\n        else:\r\n            self.log(\"[FAIL] Failed to remove Windows Hello container.\")\r\n\r\n        self.log(\"\\n\" + \"=\"*60)\r\n        self.log(\"FINAL SUMMARY\")\r\n        self.log(\"=\"*60)\r\n        for task, status in results.items():\r\n            status_text = \"[OK] SUCCESS\" if status else \"[FAIL] FAILED\"\r\n            self.log(f\"{task}: {status_text}\")\r\n        all_passed = all(results.values())\r\n        self.log(\"\\n\" + \"=\"*60)\r\n        if all_passed:\r\n            self.log(\"ALL TASKS COMPLETED SUCCESSFULLY\")\r\n            self.log(\"[INFO] IMPORTANT: Computer must be restarted for domain removal to take full effect\")\r\n        else:\r\n            failed_tasks = [task for task, status in results.items() if not status]\r\n            self.log(f\"WARNING: The following tasks failed: {, .join(failed_tasks)}\")\r\n            self.log(f\"Please check the log file for details: {self.log_file}\")\r\n        self.log(\"=\"*60)\r\n        if results.get(Domain Removal, False):\r\n            self.log(\"\\n\" + \"=\"*60)\r\n            self.log(\"RESTART REQUIRED\")\r\n            self.log(\"=\"*60)\r\n            response = input(\"\\nDo you want to restart the computer now? (yes/no): \").strip().lower()\r\n            if response in [yes, y]:\r\n                self.log(\"Restarting computer in 10 seconds...\")\r\n                time.sleep(10)\r\n                os.system(\"shutdown /r /t 0\")\r\n            else:\r\n                self.log(\"Please restart the computer manually to complete domain removal.\")\r\n        return all_passed\r\n\r\nif __name__ == \"__main__\":\r\n    try:\r\n        import ctypes\r\n        is_admin = ctypes.windll.shell32.IsUserAnAdmin()\r\n        if not is_admin:\r\n            print(\"WARNING: This script MUST be run as Administrator!\")\r\n            print(\"User management, uninstallation, and domain operations require admin privileges.\")\r\n            input(\"Press Enter to continue anyway or Ctrl+C to exit...\")\r\n    except:\r\n        pass\r\n    print(\"Uninstall Script with Automatic Retry, User Management, and Domain Removal\")\r\n    print(\"=\"*80)\r\n    try:\r\n        max_retries = int(input(\"Enter maximum retry attempts (default 5): \") or \"5\")\r\n    except ValueError:\r\n        max_retries = 5\r\n    try:\r\n        retry_delay = int(input(\"Enter delay between retries in seconds (default 30): \") or \"30\")\r\n    except ValueError:\r\n        retry_delay = 30\r\n    verifier = UninstallVerifier(max_retries=max_retries, retry_delay=retry_delay)\r\n    success = verifier.run_all()\r\n    print(f\"\\nComplete log saved to: {verifier.log_file}\")\r\n    if not verifier.check_domain_status()[0]:\r\n        print(\"Remember to restart the computer to complete domain removal!\")\r\n    input(\"\\nPress Enter to exit...\")", "type": "text"}]}'::jsonb, NULL::integer, '2025-12-02T08:44:11.861282'::timestamptz - interval '1 second'),
