    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'fgEuRzhRQ36K-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'fgEuRzhRQ36K-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "השאלה מי יותר גדול, ליאו מסי או כריסטיאנו רונאלדו, היא נושא לדיון נרחב בתקשורת ובין אוהדי כדורגל בעולם. לשניהם הישגים מרשימים ומספרים מדהימים בקריירה שלהם, אך כל אחד מהם מצטיין בסגנון וביכולות שונות.\n\nמסי ידוע בשליטה וביכולות הטכנית העילאיות שלו, וכן בשל היכולת שלו להבקיע שערים וליצור הזדמנויות לחבריו לקבוצה באופן יוצא דופן. הוא זכה בפרסים רבים, כולל זכיות רבות בכדור הזהב.\n\nרונאלדו, לעומת זאת, מתאפיין באתלטיות המרשימה שלו, מהירות כוח והמשחק האווירי שלו. גם הוא זכה במספר כדורי זהב ויש לו הישגים רבים גם כן.\n\nבסופו של דבר, ההעדפה בין השניים היא עניין של טעם אישי וסובייקטיבי, ומושפעת לעיתים קרובות מהקבוצות שאנשים אוהדים ומהסגנון שהם מעדיפים.", "type": "text"}]}'::jsonb, 4355, '2026-04-12T08:14:23.134310'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '8979nFRlnFz7-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '8979nFRlnFz7-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "מה קורה?", "type": "text"}]}'::jsonb, NULL::integer, '2025-09-22T07:22:50.908020'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '8979nFRlnFz7-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '8979nFRlnFz7-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "הכול טוב, תודה ששאלת! איך אני יכול לעזור לך היום?", "type": "text"}]}'::jsonb, 0, '2025-09-22T07:22:50.908020'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '6XL6rKqQutsY-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '6XL6rKqQutsY-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "סכם", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-18T13:37:57.858328'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '6XL6rKqQutsY-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, '6XL6rKqQutsY-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "מצטער, אני זקוק לעוד מידע כדי להבין את ההקשר. אנא ספק את תמליל השיחה כך שאוכל לסכם אותו עבורך.", "type": "text"}]}'::jsonb, 2036, '2025-05-18T13:37:57.858328'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'ZvAF3gAwPiNH-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'ZvAF3gAwPiNH-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "תעתיק\r\n31 במרץ 2025, 11:10לפנה״צ\r\n\r\nBen Levy   0:04\r\nטרנסקריפשטיין, סטארט אפ בא אליי לך כן? עכשיו הוא אמר לי.\r\n\r\nLilach Arik   0:08\r\nמעולה תקוע לי.\r\nמה אתה אומר?\r\n\r\nBen Levy   0:12\r\nאני אוריד את המצלמה.\r\nשהאינטרנט, כאילו עכשיו את שומעת את זה יותר טוב. תורידי גם את שנייה את המצלמה.\r\n\r\nLilach Arik   0:20\r\nכן, יש מצב שזה האינטרנט פה לא עובד, אז אני על האינטרנט של הטלפון שלי. זה גם יכול להיות.\r\n\r\nBen Levy   0:24\r\nכן סגור, סגור, סגור, אני שולח לך איזה סרטון, אני רוצה שתראי שניה.\r\n\r\nLilach Arik   0:42\r\nזה כאילו.\r\nשנייה.\r\nבדיוק.\r\n\r\nBen Levy   1:26\r\nעוד מעט טוב, תקשיבי. תכף בינתיים בוא נמשיך לדבר אז.\r\nהרובוט אמור למשוך תשומת לב.\r\nלגרום לאנשים להוריד את את האפליקציה. זה מה שהרובוט טוב ולעשות.\r\nקובי, את הולכת בחנות? פתאום את רואה רובוט שניגש אלייך אומר לך מה קורה, טוב. אם את רוצה לקבל מבצע. תורידי את האפליקציה הזו. מציק לך? קיו אר קוד.\r\nהורדת את הכיורקות זה, הוא ממשיך הלאה ללקוח בא.\r\nנכון שמה מראים מבצעים והכל עכשיו?\r\nהשלב הבא בסיפור הזה?\r\nזה לזהות פעם הבאה שהיוזר מגיע ולאסוף עליו נתונים.\r\nאיך? איך הנתונים נאספים? יש טכנולוגיה שנקראת איי ביקון תרשמי.\r\n\r\nLilach Arik   2:27\r\nהיי.\r\n\r\nBen Levy   2:27\r\nהנה האיי ביואן זה של אפל, איי בי קוב.\r\n\r\nLilach Arik   2:35\r\nשל סבבה?\r\n\r\nBen Levy   2:38\r\nמה זה ה bיקון? זה כאילו ביקונים כאלה שאתה שם ברחבי החנות.\r\nוהם, כאילו עובדים, והאפליקציה יודעת כאילו לזהות שהוא שהם לידה.\r\n\r\nLilach Arik   2:55\r\nשמן לדה.\r\n\r\nBen Levy   2:57\r\nהיוזר מגיע יוזר. הוא יודע לעד איזה ביקקו הוא נמצא.\r\n\r\nLilach Arik   3:03\r\nזה כאילו סוג של כזה. בוא נגיד קופסאות כאלה שאנחנו.\r\nמניחים לאורך החנות כזה באזורים מסוימים ואז הם בעצם יודעים לנווט את ממש כמו שיש לי איזה משהו כזה.\r\n\r\nBen Levy   3:14\r\nאתה לא לנווה תהרוגוט? מעכשיו מהפעם השנייה שהיוזר.\r\nהפעם השנייה שהיוזר הגיע.\r\n\r\nLilach Arik   3:20\r\nחברה.\r\n\r\nBen Levy   3:24\r\nלחנות הרובוט כבר לא משחק תפקיד.\r\nהאפליקציה יש לו כבר את האפליקציה והאפליקציה משחקת עכשיו תפקיד והאפליקציה אוטומטית מזהה שהיא כאילו ליד הביקונים. ועכשיו תחשבי שיש לך כל מיני נקודות בחנות.\r\n\r\nLilach Arik   3:28\r\nכן.\r\nהבנתי.\r\n\r\nBen Levy   3:38\r\nשאת שהאפליקציה יכולה להגיד אני עכשיו, ליד המדף הזה.\r\nאת יכולה להגיד כמה זמן כאילו?\r\nאז מה זה? מה את יכולה לעשות? את יכולה לאסוף מידע על איפה הוא מטייל בחיים. את יכולה לעשות את הסיבוב שהוא עשה, נגיד שזה גם משנה נגיד שהוא נכנס. את רואה איזה איזה סיבובים הם עושים, איפה הם ואז את יכולה, אולי לאסוף מידע על כאילו.\r\nמה הציונים הכללי? מה הסיבוב הכללי שאם זה רוצה, ואז הם יכולים למקם את הדברים אחרת.\r\n\r\nLilach Arik   4:04\r\nרוצה לדעת איזה סיבוב הוא עשה ואם הוא ביצע רכישה.\r\n\r\nBen Levy   4:11\r\nלמה היוזרים היו ליד איזה מדף מסוים?\r\nזה נגיד מה שאת יכולה, ואחר כך אולי אפשר לאמת את זה.\r\nגם אם קניה, כלומר, אם הוא קנה בסוף, הוא נותן את, הוא נותן את הטלפון שלו.\r\n\r\nLilach Arik   4:26\r\nאני רוצה להבין.\r\n\r\nBen Levy   4:28\r\nלעשות הצלבות כאילו סתם אני חושב.\r\n\r\nLilach Arik   4:32\r\nזהו, אני חושבת שבסופו של דבר מה שמעניין כנראה יעניין אותם. זה כאילו במיוחד העזיבת עגלה שזה מושג די ידוע בקמעונאות שכאילו כמה לקוחות. בסופו של דבר בייצור רכישה וכמה ששכו. כאילו אני חושבת שכמה זמן מישהו שהה במחלקה מסוימת או באזור מסוים, ואם הוא בסופו של דבר נמצא רכישה בסוף הקנייה שלו.\r\nשזה כאילו שזה כאילו מעגל משתמש, כאילו שהוא נהוג כאילו לנסות להוכיח.\r\nואז אחרי זה להבין כאילו מבחינה שיווקית אתה מתחיל להבין מה, או קיי, איך אני משנה את הזה כדי לראות אם יותר אנשים מגיעים?\r\nלסביבה וכוכשים כאילו מבצעים את הרכישה הסופית.\r\n\r\nBen Levy   5:19\r\nנכון?\r\n\r\nLilach Arik   5:23\r\nאו קיי, אז בעצם הוא יודע לזהות. אני מדברת על האיי בי פום נכון.\r\nאז הוא בעצם יודע לזהות את המיקום, הוא יודע לזהות זמנים נכון.\r\nשומע אותי.\r\n\r\nBen Levy   5:41\r\nנכון, כן, כן.\r\n\r\nLilach Arik   5:43\r\nכן, אז מיקום זמנים.\r\nויש אפשרות לדעת אנחנו נוכל לזהות איזה בן אדם זה היה.\r\n\r\nBen Levy   5:54\r\nכן, בטח. איזה בן אדם בטח.\r\n\r\nLilach Arik   5:54\r\nכאילו?\r\nאז אני נגיד, מציבה אחד גם ליד הקופה. ואז, אם בסופו של דבר נגיד אחד בכניסה אחד בקופה ואחד בכל מחלקה ואני בסופו של דבר יכולה לדעת ממש באיזה מחלקות עובה, כמה זמן הוא נשאר שם?\r\nוכמובן שיש גם את הפרטים היבשים כמו טלפון. אני חלל לקשר בין חנויות אחרות שהוא היה בן או שזה לא רלוונטי או כמה פעמים.\r\n\r\nBen Levy   6:24\r\nכרגע זה פי לחנות אחת.\r\n\r\nLilach Arik   6:28\r\nזה פירסי נכון אחת, אז בוא נגיד שאנחנו רוצים לדעת כמה פעמים הוא חזר נגיד לאותה חנות.\r\nנכון, ואנחנו רוצים גם לדעת איזה מחלקה הוא היה בה יותר מפעם אחת. אם מישהו חוזר מהמחלקה ירון פעם אחת, אז אני יכולה לדעת.\r\nשבעצם הוא מעוניין, ואז אני עושה לו פושים של מוצרים שקשורים לאותה החלקה.\r\nעוד מישהו שכתוב לו?\r\n\r\nBen Levy   6:54\r\nנכון?\r\n\r\nLilach Arik   6:58\r\nאוקיי?\r\nאז נראה לי שבאופן כללי ודי ברור, כאילו אני יכולה לעשות איזה משהו כזה נראה לי שזה הסברת לי. כאילו את את העניין. באיזה ניסיתי להבין על הרובוט יותר. אבל לפני שאתה אומר לי שזה עמדות מוכנות שיודעות לזהות לפי הטלפון.\r\nזה מקל עליי מבחינת אפיון.\r\n\r\nBen Levy   7:19\r\nמעולה, מעולה.\r\n\r\nLilach Arik   7:20\r\nיש, יש משהו שאני צריכה לשים דגש עליו?\r\n\r\nBen Levy   7:21\r\nנדבר בחצי מתוס.\r\n\r\nLilach Arik   7:27\r\nביי?\r\n\r\nLilach Arik התעתוק הופסק\r\n", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-18T13:38:30.902967'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'ZvAF3gAwPiNH-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'ZvAF3gAwPiNH-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "**Summary of the Microsoft Teams Conversation:**\n\n**Participants:**\n- Ben Levy\n- Lilach Arik\n\n**Key Topics Discussed:**\n1. **Technical Issues:**\n   - Lilach experienced connectivity issues and switched to her phones internet.\n   - Ben suggested turning off the camera to improve the connection.\n\n2. **Introduction of a Robot for Marketing:**\n   - Ben discussed a robot designed to attract attention and encourage customers to download an application.\n   - The robots role includes approaching customers in-store and promoting app downloads through QR codes.\n\n3. **Data Collection and Analysis:**\n   - Ben introduced the concept of iBeacon technology for tracking users location and behavior in the store.\n   - He explained that iBeacons can help identify patterns such as frequent visits to particular sections and overall navigation in the store.\n\n4. **User Behavior Insights:**\n   - Lilach and Ben discussed how data from iBeacons can be used to understand customer behavior, including time spent in different areas and purchase decisions.\n   - They highlighted the importance of analyzing cart abandonment and identifying why customers leave certain sections without purchasing.\n\n5. **Marketing Strategies:**\n   - Lilach proposed using the data to send targeted push notifications for products related to frequently visited sections.\n   - They discussed the potential for improving store layout and marketing strategies based on collected data.\n\n**Issues Raised:**\n- Connectivity and internet issues affecting the call quality.\n- Understanding the functionality and implementation of iBeacon technology.\n\n**Participant Requests:**\n- Lilach requested clarification on how iBeacon technology works and its application.\n- She sought details on specific data points that can be collected, such as user identification and visit frequency.\n\n**Responses Given:**\n- Ben provided detailed explanations about iBeacon technology and its capabilities.\n- He confirmed that iBeacons could collect data on user locations, time spent, and frequency of visits.\n\n**Follow-up Actions Required:**\n1. **Improve Connectivity:**\n   - Ensure stable internet connection for future calls.\n   - Test and troubleshoot connection issues before meetings.\n\n2. **Implement iBeacon Technology:**\n   - Research and integrate iBeacon devices in the store.\n   - Set up iBeacon placements strategically throughout the store.\n\n3. **Data Analysis and Usage:**\n   - Develop a system for collecting and analyzing data from iBeacons.\n   - Create marketing strategies based on user behavior insights.\n   - Implement targeted push notifications for frequent visitors of specific sections.\n\n4. **Further Discussion:**\n   - Schedule a follow-up meeting to discuss the implementation details and any additional questions Lilach might have.", "type": "text"}]}'::jsonb, 5584, '2025-05-18T13:38:30.902967'::timestamptz),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'JpuXgXLGpbbq-user-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'JpuXgXLGpbbq-user'), 0, 'message'::message_content_blocks_type_enum, '{"role": "user", "type": "message", "content": [{"text": "תרגם לעברית", "type": "text"}]}'::jsonb, NULL::integer, '2025-05-18T13:38:51.023729'::timestamptz - interval '1 second'),
    (migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'JpuXgXLGpbbq-assistant-block-0'), migration.deterministic_uuid_v4('0b1e4c6a-1f4a-4b6e-8c3d-2a5f7e9d0c1b'::uuid, 'JpuXgXLGpbbq-assistant'), 0, 'message'::message_content_blocks_type_enum, '{"role": "assistant", "type": "message", "content": [{"text": "**סיכום השיחה ב-Microsoft Teams:**\n\n**משתתפים:**\n- בן לוי\n- לילך אריק\n\n**נושאים עיקריים שנידונו:**\n1. **בעיות טכניות:**\n   - לילך חוותה בעיות התחברות ועברה לשימוש באינטרנט של הטלפון שלה.\n   - בן הציע לכבות את המצלמה כדי לשפר את החיבור.\n\n2. **הצגת רובוט לשיווק:**\n   - בן דיבר על רובוט שתוכנן למשוך תשומת לב ולעודד לקוחות להוריד אפליקציה.\n   - התפקיד של הרובוט כולל פנייה ללקוחות בחנות וקידום הורדת האפליקציה באמצעות קודי QR.\n\n3. **איסוף וניתוח נתונים:**\n   - בן הציג את הקונספט של טכנולוגיית iBeacon למעקב אחרי מיקום והתנהגות המשתמשים בחנות.\n   - הוא הסביר ש-iBeacons יכולים לעזור בזיהוי דפוסים כמו ביקורים תכופים באזורים מסוימים וניווט כללי בחנות.\n\n4. **תובנות על התנהגות משתמשים:**\n   - לילך ובן דיברו על איך אפשר להשתמש בנתונים מ-iBeacons כדי להבין את התנהגות הלקוחות, כולל זמן השהייה באזורים שונים והחלטות רכישה.\n   - הם הדגישו את החשיבות בניתוח נטישת עגלות וזיהוי הסיבות לכך שלקוחות עוזבים אזורים מסוימים בלי לבצע רכישה.\n\n5. **אסטרטגיות שיווקיות:**\n   - לילך הציעה להשתמש בנתונים כדי לשלוח התראות פוש ממוקדות עבור מוצרים שקשורים לאזורים שביקרו בהם לעיתים קרובות.\n   - הם דיברו על האפשרות לשפר את סידור החנות ואסטרטגיות השיווק על בסיס הנתונים שנאספו.\n\n**בעיות שהועלו:**\n- בעיות התחברות ואינטרנט שהשפיעו על איכות השיחה.\n- הבנת התפקוד והיישום של טכנולוגיית iBeacon.\n\n**בקשות המשתתפים:**\n- לילך ביקשה הבהרות בנוגע לאופן הפעולה של טכנולוגיית iBeacon ויישומה.\n- היא חיפשה פרטים על נקודות נתונים ספציפיות שניתן לאסוף, כמו זיהוי משתמשים ותדירות ביקורים.\n\n**תגובות שניתנו:**\n- בן סיפק הסברים מפורטים על טכנולוגיית iBeacon ויכולותיה.\n- הוא אישר ש-iBeacons יכולים לאסוף נתונים על מיקומי המשתמשים, זמני שהייה ותדירות ביקורים.\n\n**פעולות מעקב נדרשות:**\n1. **שיפור התחברות:**\n   - להבטיח חיבור אינטרנט יציב לפגישות עתידיות.\n   - לבדוק ולפתור בעיות התחברות לפני פגישות.\n\n2. **יישום טכנולוגיית iBeacon:**\n   - לחקור ולשלב מכשירי iBeacon בחנות.\n   - למקם את מכשירי iBeacon בצורה אסטרטגית ברחבי החנות.\n\n3. **ניתוח ושימוש בנתונים:**\n   - לפתח מערכת לאיסוף וניתוח נתונים מ-iBeacons.\n   - ליצור אסטרטגיות שיווק על בסיס תובנות התנהגות משתמשים.\n   - ליישם התראות פוש ממוקדות עבור מבקרים תכופים באזורים ספציפיים.\n\n4. **דיון נוסף:**\n   - לתזמן פגישת מעקב כדי לדון בפרטי היישום וכל שאלות נוספות שלילך עשויה להיות לה.", "type": "text"}]}'::jsonb, 7312, '2025-05-18T13:38:51.023729'::timestamptz),
